/**
 * Full-size ASCII Color badges: the character grid for each badge and tier,
 * exported from the badge gallery (hq-accomplishment-badges, ASCII Color
 * direction) so the app draws exactly what the design shows.
 *
 * Each variant is 24 rows of 48 cells. `chars` holds the glyph per cell (space
 * for empty), `colors` holds an index into `palette` per cell (`.` for empty),
 * using the alphabet below. Palette entries are "#rrggbb@alpha".
 *
 * Generated data. Re-export from the gallery instead of editing by hand.
 * Loaded lazily: only the badge detail view needs it.
 */

export const PALETTE_ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_-";

export interface AsciiArt {
  chars: readonly string[];
  colors: readonly string[];
  palette: readonly string[];
}

